#include "dwg2dxf/dx_iface.h"
#include "dwg2dxf/dx_data.h"
#include <cmath>
#include <iostream>

class DxIfaceMaterialReferenceTestAccess {
public:
    static bool qualified(const dx_iface& adapter,std::uint32_t original,std::uint32_t target) {
        if(!adapter.m_dxfMLineStylesInspected || !adapter.m_dxfMLineLinetypesInspected
            || adapter.m_dxfMLineConsumerInspected!=3u || adapter.m_dxfMLineConsumers.size()!=2u)return false;
        for(const auto handle:{original,target}) {
            const auto row=adapter.m_dxfMLineStyles.find(handle);
            if(row==adapter.m_dxfMLineStyles.end() || !row->second.baseline || !row->second.linetypesBound
                || !row->second.dictionaryOrigin || !row->second.dictionaryOrigin->bodyMatched
                || !row->second.dictionaryOrigin->stateComplete || !row->second.dictionaryOrigin->originBound)return false;
        }
        for(const auto& row:adapter.m_dxfMLineConsumers)
            if(!row.second.original || row.second.original->styleHandle!=original)return false;
        return true;
    }
};

bool sameGeometry(const DRW_MLineStyle& a,const DRW_MLineStyle& b) {
    if(a.flags!=b.flags || a.startAngle!=b.startAngle || a.endAngle!=b.endAngle
        || std::signbit(a.startAngle)!=std::signbit(b.startAngle)
        || std::signbit(a.endAngle)!=std::signbit(b.endAngle)
        || a.elements.size()!=b.elements.size())return false;
    for(std::size_t i=0;i<a.elements.size();++i)
        if(a.elements[i].offset!=b.elements[i].offset
            || std::signbit(a.elements[i].offset)!=std::signbit(b.elements[i].offset))return false;
    return true;
}
int main(int argc,char** argv) {
    if(argc!=3)return 2;
    dx_iface adapter;dx_data data;
    if(!adapter.fileImport(argv[1],&data,false))return 2;
    const DRW_MLineStyle* target=nullptr;
    for(const auto& dictionary:data.dictionaries)for(const auto& entry:dictionary.m_entries)
        if(entry.m_name=="PeerRetarget")for(const auto& style:data.mLineStyles)
            if(style.handle==entry.m_handle && style.parentHandle==dictionary.handle) {
                if(target)return 2;target=&style;
            }
    if(!target || !data.mBlock)return 2;
    DRW_MLine* selected=nullptr;
    for(auto* entity:data.mBlock->ent)if(entity && entity->eType==DRW::MLINE) {
        if(selected)return 2;selected=dynamic_cast<DRW_MLine*>(entity);
    }
    if(!selected || selected->styleHandle==target->handle)return 2;
    const DRW_MLineStyle* original=nullptr;
    for(const auto& style:data.mLineStyles)if(style.handle==selected->styleHandle) {
        if(original)return 2;original=&style;
    }
    if(!original || !sameGeometry(*original,*target))return 2;
    const auto before=selected->styleHandle;const auto name=selected->styleName;
    const std::string unchanged=std::string(argv[2])+".unchanged.dxf";
    if(!adapter.fileExport(unchanged,data.sourceVersion,false,&data,false,true,
            dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless)
        || !DxIfaceMaterialReferenceTestAccess::qualified(adapter,before,target->handle))return 2;
    selected->styleHandle=target->handle;
    const bool accepted=adapter.fileExport(argv[2],data.sourceVersion,false,&data,false,true,
        dx_dxfSourceTextPolicy::RequireValidSource,DRW::DxfTextWritePolicy::RequireLossless);
    std::cout<<"sourceStyles="<<data.mLineStyles.size()<<"; geometryCompatible=1; original340="<<before
        <<"; selected340="<<target->handle<<"; originalAndTargetAuthorityQualified=1; originalConsumersQualified=2; exportAccepted="<<accepted
        <<"; requestedHandleAndRedundantNameRetained="<<(selected->styleHandle==target->handle && selected->styleName==name)<<'\n';
    return accepted?0:1;
}
